import { test, expect } from '@playwright/test';

const API_BASE_URL = process.env.API_BASE_URL ?? 'http://localhost:5000';

// ─────────────────────────────────────────────────────────────────────────────
// [P1] OpenAPI / Scalar surface — edge cases beyond ATDD happy path
// ─────────────────────────────────────────────────────────────────────────────

test.describe('[API] Scalar & OpenAPI surface — edge cases', () => {
  test('[P1] should redirect bare root path "/" to the Scalar documentation page', async ({ request }) => {
    // GIVEN: Program.cs maps "/" → Redirect("/scalar")
    // WHEN: A GET is issued to the root with redirects disabled
    const response = await request.get(`${API_BASE_URL}/`, { maxRedirects: 0 });

    // THEN: Server returns a 3xx redirect pointing at /scalar
    expect([301, 302, 307, 308]).toContain(response.status());
    const location = response.headers()['location'] ?? '';
    expect(location.toLowerCase()).toContain('scalar');
  });

  test('[P1] should serve a valid OpenAPI 3.x document at /openapi/v1.json', async ({ request }) => {
    // GIVEN: app.MapOpenApi() is registered for Scalar consumption
    // WHEN: The OpenAPI JSON endpoint is fetched
    const response = await request.get(`${API_BASE_URL}/openapi/v1.json`);

    // THEN: 200 OK with a JSON document declaring OpenAPI 3.x and SiesaAgents.API as title
    expect(response.status()).toBe(200);
    const contentType = response.headers()['content-type'] ?? '';
    expect(contentType).toContain('json');
    const body = await response.json();
    expect(body).toHaveProperty('openapi');
    expect(String(body.openapi)).toMatch(/^3\./);
    expect(body).toHaveProperty('info.title');
    expect(String(body.info.title)).toContain('SiesaAgents.API');
  });

  test('[P2] should reject HTTP POST on /scalar (read-only documentation surface)', async ({ request }) => {
    // GIVEN: /scalar is a GET-only documentation endpoint
    // WHEN: A POST is attempted against /scalar
    const response = await request.post(`${API_BASE_URL}/scalar`, { data: {} });

    // THEN: Response is 404 or 405 — never 200 (no accidental write side effects)
    expect([404, 405]).toContain(response.status());
  });

  test('[P2] should reject HTTP DELETE on /scalar', async ({ request }) => {
    // GIVEN: /scalar is documentation; mutating verbs must not succeed
    // WHEN: DELETE is sent
    const response = await request.delete(`${API_BASE_URL}/scalar`);

    // THEN: Not allowed / not found
    expect([404, 405]).toContain(response.status());
  });

  test('[P2] should not expose the legacy Swagger UI at /swagger/index.html', async ({ request }) => {
    // GIVEN: Swashbuckle is explicitly forbidden — only Scalar is permitted
    // WHEN: The classic Swashbuckle path is probed
    const response = await request.get(`${API_BASE_URL}/swagger/index.html`);

    // THEN: 404 (endpoint must not exist)
    expect(response.status()).toBe(404);
  });

  test('[P2] should not expose any /api-docs or alternate documentation aliases', async ({ request }) => {
    // GIVEN: Only /scalar is the sanctioned documentation surface
    // WHEN: Common alternate doc paths are probed
    const aliases = ['/api-docs', '/docs', '/redoc'];

    for (const alias of aliases) {
      const response = await request.get(`${API_BASE_URL}${alias}`);
      // THEN: None of these aliases should return 200
      expect(response.status(), `Alias ${alias} unexpectedly served content`).not.toBe(200);
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// [P0] CORS — edge cases beyond ATDD happy path
// ─────────────────────────────────────────────────────────────────────────────

test.describe('[API] CORS policy — edge cases', () => {
  test('[P0] should NOT set Access-Control-Allow-Origin for a disallowed origin', async ({ request }) => {
    // GIVEN: DevCors only allows http://localhost:5173
    // WHEN: A request arrives with an arbitrary external origin
    const response = await request.get(`${API_BASE_URL}/openapi/v1.json`, {
      headers: { Origin: 'http://evil.example.com' },
    });

    // THEN: The CORS allow-origin header either is missing entirely or echoes the allowed origin
    // (never echoes the foreign origin — that would be a misconfiguration)
    const allowOrigin = response.headers()['access-control-allow-origin'] ?? '';
    expect(allowOrigin).not.toBe('http://evil.example.com');
  });

  test('[P1] should respond to OPTIONS preflight with Access-Control-Allow-Methods header', async ({ request }) => {
    // GIVEN: AllowAnyMethod() is configured for DevCors
    // WHEN: A CORS preflight is sent with a custom method requirement
    const response = await request.fetch(`${API_BASE_URL}/openapi/v1.json`, {
      method: 'OPTIONS',
      headers: {
        Origin: 'http://localhost:5173',
        'Access-Control-Request-Method': 'POST',
        'Access-Control-Request-Headers': 'Content-Type, Authorization',
      },
    });

    // THEN: Preflight succeeds AND advertises permitted methods/headers
    expect([200, 204]).toContain(response.status());
    const allowMethods = response.headers()['access-control-allow-methods'] ?? '';
    expect(allowMethods.length).toBeGreaterThan(0);
  });

  test('[P1] should echo Access-Control-Allow-Headers for the requested headers in preflight', async ({ request }) => {
    // GIVEN: AllowAnyHeader() is configured
    // WHEN: A preflight requests Content-Type + a custom header
    const response = await request.fetch(`${API_BASE_URL}/openapi/v1.json`, {
      method: 'OPTIONS',
      headers: {
        Origin: 'http://localhost:5173',
        'Access-Control-Request-Method': 'GET',
        'Access-Control-Request-Headers': 'Content-Type, X-Correlation-Id',
      },
    });

    // THEN: Preflight succeeds and at minimum advertises an allow-headers list
    expect([200, 204]).toContain(response.status());
    const allowHeaders = response.headers()['access-control-allow-headers'] ?? '';
    // CORS spec: AllowAnyHeader echoes the requested headers OR sends "*"
    expect(allowHeaders.length).toBeGreaterThan(0);
  });

  test('[P2] should allow CORS on the /openapi/v1.json document for the frontend', async ({ request }) => {
    // GIVEN: Frontend may fetch the OpenAPI document directly for type generation tooling
    // WHEN: A simple GET is sent with the allowed origin
    const response = await request.get(`${API_BASE_URL}/openapi/v1.json`, {
      headers: { Origin: 'http://localhost:5173' },
    });

    // THEN: The allow-origin header matches the frontend origin or is wildcard
    const allowOrigin = response.headers()['access-control-allow-origin'] ?? '';
    expect(allowOrigin === 'http://localhost:5173' || allowOrigin === '*').toBe(true);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// [P0] Problem Details (RFC 7807) — schema fidelity on unmatched routes
// ─────────────────────────────────────────────────────────────────────────────

test.describe('[API] Problem Details RFC 7807 — unmatched routes', () => {
  test('[P0] should return application/problem+json content type on unknown route', async ({ request }) => {
    // GIVEN: UseStatusCodePages converts 404 into Problem Details
    // WHEN: An unknown route is requested
    const response = await request.get(`${API_BASE_URL}/this-route-does-not-exist-${Date.now()}`);

    // THEN: 404 with the RFC 7807 content type
    expect(response.status()).toBe(404);
    const contentType = response.headers()['content-type'] ?? '';
    expect(contentType).toContain('application/problem+json');
  });

  test('[P0] should return RFC 7807 body with status, title, type, and instance fields', async ({ request }) => {
    // GIVEN: ProblemDetails is configured with Type/Instance/Title
    // WHEN: An unknown route is hit
    const path = `/api/missing-${Date.now()}`;
    const response = await request.get(`${API_BASE_URL}${path}`);

    // THEN: The body conforms to RFC 7807 shape
    expect(response.status()).toBe(404);
    const body = await response.json();
    expect(body).toMatchObject({
      status: 404,
      title: expect.any(String),
      type: expect.stringContaining('rfc7231'),
      instance: path,
    });
  });

  test('[P1] should return RFC 7807 problem document for POST to unknown route (no method echo)', async ({ request }) => {
    // GIVEN: 404 handler should work regardless of HTTP verb
    // WHEN: A POST is sent to a missing endpoint
    const response = await request.post(`${API_BASE_URL}/api/v1/missing-${Date.now()}`, {
      data: { foo: 'bar' },
      headers: { 'Content-Type': 'application/json' },
    });

    // THEN: Still produces RFC 7807 — no HTML fallback
    expect(response.status()).toBe(404);
    const contentType = response.headers()['content-type'] ?? '';
    expect(contentType).toContain('application/problem+json');
  });

  test('[P1] should NOT leak stack trace or exception detail in Problem Details body', async ({ request }) => {
    // GIVEN: ExceptionHandlingMiddleware must never expose internals (security)
    // WHEN: Any error response is generated (here: 404)
    const response = await request.get(`${API_BASE_URL}/api/v1/leak-check-${Date.now()}`);
    const body = await response.json();

    // THEN: Common stack-trace markers must not appear anywhere in the payload
    const serialized = JSON.stringify(body).toLowerCase();
    expect(serialized).not.toContain('at siesaagents');
    expect(serialized).not.toContain('stacktrace');
    expect(serialized).not.toContain('exception');
    expect(serialized).not.toContain('system.');
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// [P2] Default template & noise removal
// ─────────────────────────────────────────────────────────────────────────────

test.describe('[API] Default template noise — must be absent', () => {
  test('[P2] should NOT expose /WeatherForecast (case-insensitive route check)', async ({ request }) => {
    // GIVEN: Default .NET webapi template scaffolding must be removed
    // WHEN: Multiple casings of the default endpoint are probed
    for (const variant of ['/weatherforecast', '/WeatherForecast', '/Weatherforecast']) {
      const response = await request.get(`${API_BASE_URL}${variant}`);
      expect(response.status(), `${variant} should not exist`).not.toBe(200);
    }
  });

  test('[P2] should NOT expose any /Class1 or generated default endpoints', async ({ request }) => {
    // GIVEN: Class1.cs from class library template must be deleted
    // WHEN: The default class name is probed as a route
    const response = await request.get(`${API_BASE_URL}/Class1`);

    // THEN: 404
    expect(response.status()).toBe(404);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// [P2] Resilience — concurrent and unusual requests must not destabilize the API
// ─────────────────────────────────────────────────────────────────────────────

test.describe('[API] Server resilience', () => {
  test('[P2] should handle 10 concurrent GET /scalar requests without errors', async ({ request }) => {
    // GIVEN: Kestrel default config must handle a small concurrency burst
    // WHEN: 10 GETs are fired simultaneously
    const responses = await Promise.all(
      Array.from({ length: 10 }, () => request.get(`${API_BASE_URL}/scalar`))
    );

    // THEN: Every response succeeds (200 or redirect)
    for (const response of responses) {
      expect(response.status()).toBeLessThan(400);
    }
  });

  test('[P2] should not crash when a very long URL path is requested', async ({ request }) => {
    // GIVEN: Kestrel must reject or 404 oversized URLs gracefully (no 5xx)
    // WHEN: A URL with 500 path segments is requested
    const longPath = '/' + 'a'.repeat(500);
    const response = await request.get(`${API_BASE_URL}${longPath}`);

    // THEN: 4xx (likely 404) — never 5xx (no server crash)
    expect(response.status()).toBeGreaterThanOrEqual(400);
    expect(response.status()).toBeLessThan(500);
  });

  test('[P2] should return Server: Kestrel header (sanity check the .NET host)', async ({ request }) => {
    // GIVEN: Kestrel is the production host for .NET 10
    // WHEN: Any request is made
    const response = await request.get(`${API_BASE_URL}/openapi/v1.json`);

    // THEN: The Server header advertises Kestrel (or is omitted entirely in CI hardening)
    const server = response.headers()['server'] ?? '';
    // Accept either Kestrel-branded or empty (some hardening configs strip it)
    expect(server === '' || server.toLowerCase().includes('kestrel')).toBe(true);
  });
});
